#!/usr/bin/env python3
# gpio_pwm_output_event_driven.py
# Event-driven PWM output control for Raspberry Pi using gpiozero
import gpiozero
import time
import signal
import sys

# Define GPIO pins for PWM output (BCM numbering)
PWM_GPIO_PINS = [1, 2, 3, 4]

# Global variable to track program state for clean exit
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C signal for graceful exit."""
    global running
    print("Exiting program...")
    running = False

def initialize_pwm_outputs(gpio_pins):
    """Initializes PWMOutput devices for the specified GPIO pins."""
    pwm_outputs = []
    for pin in gpio_pins:
        try:
            pwm_output = gpiozero.PWMOutput(pin)
            pwm_outputs.append(pwm_output)
        except gpiozero.exc.PinError as e:
            print(f"Error initializing PWM output on pin {pin}: {e}")
            return None  # Indicate initialization failure
    return pwm_outputs

def read_pwm_value():
    """Reads a valid PWM value from standard input."""
    while True:
        try:
            value = float(input("Enter PWM value (0.0-1.0): "))
            if 0.0 <= value <= 1.0:
                return value
            else:
                print("Invalid input. Please enter a value between 0.0 and 1.0.")
        except ValueError:
            print("Invalid input. Please enter a numeric value.")

def apply_pwm_value(pwm_outputs, value):
    """Applies the given PWM value to all initialized PWM outputs."""
    for output in pwm_outputs:
        output.value = value
        print(f"PWM output on GPIO {output.pin.number} set to {value}")

def main():
    """Main function to control PWM output using gpiozero."""
    global running

    # Register signal handler for graceful exit
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize PWM outputs
    pwm_outputs = initialize_pwm_outputs(PWM_GPIO_PINS)
    if pwm_outputs is None:
        print("Failed to initialize PWM outputs. Exiting.")
        sys.exit(1)

    print("PWM output initialized. Press Ctrl+C to exit.")

    try:
        while running:
            # Read PWM value from user
            pwm_value = read_pwm_value()

            # Apply PWM value to all outputs
            apply_pwm_value(pwm_outputs, pwm_value)

            # Wait for a short interval
            time.sleep(0.1)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure proper cleanup on exit
        print("Cleaning up...")
        if pwm_outputs:
            for output in pwm_outputs:
                output.close()
        print("Program finished.")

if __name__ == "__main__":
    main()

