from gpiozero import DigitalOutputDevice
import sys

RELAY_PIN = 17

def setup_relay(pin_number):
    """Create a gpiozero DigitalOutputDevice object for the relay."""
    # Initialize the relay pin as an output
    relay_device = DigitalOutputDevice(pin_number)
    return relay_device

def apply_state(relay_device, turn_on):
    """Set the relay state and report it."""
    # Turn the relay on or off based on the turn_on flag
    if turn_on:
        relay_device.on()
        print("Relay ON")
    else:
        relay_device.off()
        print("Relay OFF")

if __name__ == "__main__":
    # Parse the command-line argument to determine the relay state
    if len(sys.argv) < 2:
        print("Usage: relay_control.py <on|off>")
        sys.exit(1)
    state_command = sys.argv[1].lower()
    try:
        # Initialize the relay
        relay = setup_relay(RELAY_PIN)
        # Apply the requested state
        if state_command == "on":
            apply_state(relay, True)
        elif state_command == "off":
            apply_state(relay, False)
        else:
            print("Invalid state. Use 'on' or 'off'.")
    except Exception as error:
        # Handle any errors during relay control
        print(f"Error controlling relay: {error}")
    finally:
        # Ensure the relay is released on exit
        if 'relay' in locals():
            relay.close()

import time
import board
import busio
import adafruit_mcp3xxx.mcp3008 as MCP3008

# Sampling interval in seconds for the hydroponics control loop
SAMPLE_INTERVAL = 60


def create_spi_bus():
    """Create and return the SPI bus object."""
    return busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)


def create_adc(spi_bus):
    """Create and return the MCP3008 ADC object."""
    return MCP3008.MCP3008(spi_bus)


def read_channel(adc_device, channel_number):
    """Read a single channel from the ADC and return the raw value."""
    return adc_device.read(channel_number)


def validate_reading(reading_value):
    """Validate that the ADC reading is within a reasonable range."""
    return 0 <= reading_value <= 1023


def main():
    """Main function to sample the ADC and print readings."""
    spi_bus = create_spi_bus()
    adc_device = create_adc(spi_bus)
    try:
        for sample_index in range(5):
            raw_reading = read_channel(adc_device, 0)
            if validate_reading(raw_reading):
                print(f"Sample {sample_index + 1}: {raw_reading}")
            else:
                print(f"Invalid reading: {raw_reading}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("Sampling interrupted by user.")
    finally:
        # No specific cleanup needed for adafruit_mcp3xxx, but good practice to include
        spi_bus.deinit()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# Simple relay control program for Raspberry Pi using gpiozero
# Target: Raspberry Pi 3 Model B+
# Context: STEM education

import time
from gpiozero import DigitalOutputDevice

RELAY_GPIO_PIN = 17  # GPIO pin connected to the relay

def initialize_relay(pin_number):
    """Initialize the relay object."""
    try:
        relay = DigitalOutputDevice(pin_number, active_high=True, initial_value=False)
        return relay
    except Exception as e:
        print(f"Error initializing relay: {e}")
        return None

def toggle_relay(relay_device):
    """Toggle the relay state."""
    if relay_device is None:
        return

    try:
        relay_device.toggle()  # Toggle the relay state
        current_state = "ON" if relay_device.is_active else "OFF"
        print(f"Relay state: {current_state}")
    except Exception as e:
        print(f"Error toggling relay: {e}")

def main():
    """Main function to control the relay."""
    relay = initialize_relay(RELAY_GPIO_PIN)

    if relay is None:
        print("Failed to initialize relay. Exiting.")
        return 1  # Indicate an error

    try:
        while True:
            toggle_relay(relay)
            time.sleep(0.1)  # Short delay to avoid excessive CPU usage
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        if relay:
            relay.close()  # Release the GPIO pin
            print("Relay released.")
        print("Exiting program.")
        return 0  # Indicate successful exit

if __name__ == "__main__":
    main()

