# PCA9685 Servo Driver Demo for Raspberry Pi
# Demonstrates servo control using gpiozero library
# Target: Raspberry Pi 3 Model B+

import time
import sys
from gpiozero import PCA9685

# Constants
SERVO_MIN = 150  # Minimum pulse length out of 4096
SERVO_MAX = 600  # Maximum pulse length out of 4096
SERVO_MID = (SERVO_MAX - SERVO_MIN) // 2 + SERVO_MIN

# Initialize PCA9685
try:
    pwm_controller = PCA9685()
    pwm_controller.frequency = 60  # Set PWM frequency
except Exception as e:
    print(f"Error initializing PCA9685: {e}")
    sys.exit(1)


def set_servo_pulse(channel, pulse):
    """
    Sets the servo pulse width for a given channel.

    Args:
        channel (int): The PWM channel (0-15).
        pulse (int): The pulse width (150-600).
    """
    try:
        if not 0 <= channel <= 15:
            raise ValueError("Channel must be between 0 and 15")
        if not SERVO_MIN <= pulse <= SERVO_MAX:
            raise ValueError(f"Pulse must be between {SERVO_MIN} and {SERVO_MAX}")

        pwm_controller.channels[channel].value = (pulse - SERVO_MIN) / (SERVO_MAX - SERVO_MIN)
    except ValueError as e:
        print(f"Invalid input: {e}")
    except Exception as e:
        print(f"Error setting servo pulse: {e}")


def main():
    """
    Main function to control servo motors.
    """
    try:
        while True:
            command = input("Enter command (e.g., 'set 0 300', 'exit'): ")
            if command.lower() == "exit":
                print("Exiting program.")
                break

            try:
                parts = command.split()
                if parts[0] == "set" and len(parts) == 3:
                    channel = int(parts[1])
                    pulse = int(parts[2])
                    set_servo_pulse(channel, pulse)
                    print(f"Servo {channel} set to pulse {pulse}")
                else:
                    print("Invalid command. Usage: 'set <channel> <pulse>'")

            except (IndexError, ValueError):
                print("Invalid command format.")

            except Exception as e:
                print(f"An error occurred: {e}")

    except KeyboardInterrupt:
        print("\nProgram interrupted. Cleaning up...")
    finally:
        pwm_controller.close()  # Release the PCA9685
        print("Program finished.")


if __name__ == "__main__":
    main()

