    """Sets up the relay pin as an output."""
    try:
        relay = DigitalOutputDevice(pin_number)
        return relay
    except Exception as e:
        print(f"Error setting up relay: {e}")
        sys.exit(1)

def set_relay_state(relay, state):
    """Sets the relay state (True for ON, False for OFF)."""
    try:
        relay.value = state
        return state
    except Exception as e:
        print(f"Error setting relay state: {e}")
        return None

def report_state(state):
    """Prints the current relay state."""
    if state is not None:
        print(f"Relay is now {'ON' if state else 'OFF'}")

def main():
    """Main function to control the relay."""
    try:
        relay = setup_relay(RELAY_PIN)
        desired_state = True  # Turn the relay ON
        new_state = set_relay_state(relay, desired_state)
        report_state(new_state)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # Ensure the relay is released when the program exits
        if 'relay' in locals():
            relay.close()
        sys.exit(0)

if __name__ == "__main__":
