import time
import board
import adafruit_dht

# GPIO pins for the DHT22 sensors (BCM numbering)
sensor_pins = [board.D4, board.D5, board.D17, board.D23]

# Create DHT22 sensor objects for each pin
sensors = [adafruit_dht.DHT22(pin) for pin in sensor_pins]


def read_sensor_data(sensor):
    """Read temperature and humidity from a DHT22 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as error:
        # DHT22 sensors sometimes fail to respond; treat as a reading failure
        print(f"Sensor read error: {error}")
        return None, None


def validate_reading(temperature, humidity):
    """Check if temperature and humidity readings are valid."""
    if temperature is None or humidity is None:
        return False
    return -40 <= temperature <= 80 and 0 <= humidity <= 100


def report_state(sensor_index, temperature, humidity):
    """Print the sensor state to standard output."""
    if temperature is not None and humidity is not None:
        print(f"Sensor {sensor_index}: Temp={temperature:.1f}C Humidity={humidity:.1f}%")
    else:
        print(f"Sensor {sensor_index}: No valid reading")


def main():
    """Continuously read and report sensor data."""
    try:
        while True:
            for i, sensor in enumerate(sensors):
                temperature, humidity = read_sensor_data(sensor)
                if validate_reading(temperature, humidity):
                    report_state(i, temperature, humidity)
                else:
                    report_state(i, None, None)
            time.sleep(60)  # Wait 60 seconds before the next reading
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # Release the DHT22 sensors to free the GPIO pins
        for sensor in sensors:
            sensor.exit()
        print("GPIO resources released.")


if __name__ == "__main__":
    main()

