# I2C address of the PCF8574 backpack driving the relay module
RELAY_ADDRESS = 0x27


def read_relay_state(i2c_bus):
    """Read a single byte from the relay module and return its value."""
    # Read a byte from register 0 on the relay backpack
    try:
        return i2c_bus.read_byte(RELAY_ADDRESS)
    except OSError as bus_error:
        logging.error("I2C read failed: %s", bus_error)
        return None


def is_valid_reading(measurement_value):
    """Check that the relay reading is a valid integer."""
    # A valid reading is a number within the allowed range
    return measurement_value is not None and 0 <= measurement_value <= 255


def main():
    """Continuously poll the relay module for hydroponics control."""
    # Open the I2C bus that the relay module is connected to
    i2c_bus = smbus2.SMBus(1)
    try:
        while True:
            measurement_value = read_relay_state(i2c_bus)
            if is_valid_reading(measurement_value):
                logging.info("Relay state: %d", measurement_value)
            else:
                logging.warning("Invalid relay reading: %s", measurement_value)
            time.sleep(2.0)
    except KeyboardInterrupt:
        logging.info("Hydroponics control stopped")
    finally:
        # Always close the I2C bus when finished
        i2c_bus.close()


