logger = logging.getLogger(__name__)

# Constants
ADC_ADDRESS = 0x48  # Default I2C address of the ADS1115
REFERENCE_VOLTAGE = 3.3  # Reference voltage for the ADS1115

def create_i2c_bus():
    """Creates and returns an I2C bus object."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        logger.error(f"Error creating I2C bus: {e}")
        return None

def create_adc(i2c_bus, address=ADC_ADDRESS):
    """Creates and returns an ADS1115 ADC object."""
    try:
        return ADS.ADS1115(i2c_bus, address=address)
    except Exception as e:
        logger.error(f"Error creating ADS1115: {e}")
        return None

def create_analog_input(adc):
    """Creates and returns an analog input channel."""
    try:
        return AnalogIn(adc, ADS.ADS1115.AIN0)
    except Exception as e:
        logger.error(f"Error creating analog input: {e}")
        return None

def read_voltage(channel):
    """Reads and returns the voltage from the given channel."""
    try:
        return channel.voltage
    except Exception as e:
        logger.error(f"Error reading voltage: {e}")
        return None

def is_valid_reading(voltage, reference_voltage=REFERENCE_VOLTAGE):
    """Checks if the voltage reading is within a valid range."""
    return 0 <= voltage <= reference_voltage

def main():
    """Main function to continuously read and print voltage readings."""
    i2c_bus = create_i2c_bus()
    if i2c_bus is None:
        sys.exit(1)

    adc = create_adc(i2c_bus)
    if adc is None:
        sys.exit(1)

    channel = create_analog_input(adc)
    if channel is None:
        sys.exit(1)

    try:
        while True:
            voltage = read_voltage(channel)
            if voltage is not None:
                if is_valid_reading(voltage):
                    print(f"Voltage: {voltage:.2f} V")
                else:
                    logger.warning(f"Invalid voltage reading: {voltage:.2f} V")
            time.sleep(0.001)
    except KeyboardInterrupt:
        logger.info("Program terminated by user.")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        logger.info("Releasing resources and exiting.")
        if i2c_bus:
            i2c_bus.deinit()
        sys.exit(0)

if __name__ == "__main__":
