#!/usr/bin/env python3

import time
import os
import logging
from picamera2 import Picamera2

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraHandler:
    """
    Handles image capture and storage using the Raspberry Pi camera.
    """

    def __init__(self, image_dir="captured_images", image_prefix="image_", validity_check=lambda x: True):
        """
        Initializes the CameraHandler.

        Args:
            image_dir (str): Directory to save images.
            image_prefix (str): Prefix for image filenames.
            validity_check (callable): Function to validate captured images.
        """
        self.image_dir = image_dir
        self.image_prefix = image_prefix
        self.validity_check = validity_check
        self.picam2 = Picamera2()
        self.picam2.configure(self.picam2.create_still_configuration())
        self._setup_directory()

    def _setup_directory(self):
        """Creates the image directory if it doesn't exist."""
        try:
            os.makedirs(self.image_dir, exist_ok=True)
            logging.info(f"Image directory set to: {self.image_dir}")
        except OSError as e:
            logging.error(f"Error creating image directory: {e}")
            raise

    def capture_image(self):
        """Captures an image and saves it to the specified directory."""
        try:
            self.picam2.start()
            time.sleep(1)  # Allow camera to warm up
            timestamp = int(time.time() * 1000)
            image_path = os.path.join(self.image_dir, f"{self.image_prefix}{timestamp}.jpg")
            self.picam2.capture_file(image_path)
            self.picam2.stop()
            logging.info(f"Image saved to: {image_path}")
            return image_path
        except Exception as e:
            logging.error(f"Error capturing image: {e}")
            self.picam2.stop()  # Ensure camera is stopped even on error
            return None

    def is_image_valid(self, image_path):
        """Checks if the captured image is valid using the provided validity check function."""
        try:
            if self.validity_check(image_path):
                logging.info("Image is valid.")
                return True
            else:
                logging.warning("Image is not valid.")
                return False
        except Exception as e:
            logging.error(f"Error checking image validity: {e}")
            return False

    def save_image(self, image_path):
        """Saves the captured image to the specified directory."""
        try:
            if image_path and self.is_image_valid(image_path):
                logging.info(f"Image saved successfully: {image_path}")
            else:
                logging.warning("Image not saved due to validity check failure or image path is None.")
        except Exception as e:
            logging.error(f"Error saving image: {e}")


def main():
    """Main function to capture and save images."""
    try:
        camera_handler = CameraHandler()
        while True:
            image_path = camera_handler.capture_image()
            camera_handler.save_image(image_path)
            time.sleep(0.01)  # Small delay to avoid busy-waiting
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.critical(f"Unhandled exception: {e}")
    finally:
        try:
            camera_handler.picam2.close() # Release camera resources
        except:
            pass
        logging.info("Exiting program.")


if __name__ == "__main__":
    main()

