#!/usr/bin/env python3
# PCA9685 Servo Driver Demo for Raspberry Pi
# Demonstrates servo control using gpiozero on a Raspberry Pi
# Subcategory: Servo Control

import gpiozero
import time
import sys

# Define GPIO pins for PCA9685 (BCM numbering)
PIN_SERVO_1 = 2
PIN_SERVO_2 = 3

# Servo value range (adjust as needed)
SERVO_MIN_VALUE = 100
SERVO_MAX_VALUE = 700


def initialize_servos():
    """Initializes the servo motors."""
    try:
        servo1 = gpiozero.Servo(PIN_SERVO_1, min_value=SERVO_MIN_VALUE / 1023, max_value=SERVO_MAX_VALUE / 1023)
        servo2 = gpiozero.Servo(PIN_SERVO_2, min_value=SERVO_MIN_VALUE / 1023, max_value=SERVO_MAX_VALUE / 1023)
        return servo1, servo2
    except gpiozero.exc.GPIODeviceError as e:
        print(f"Error initializing servos: {e}")
        sys.exit(1)


def set_servo_position(servo, value):
    """Sets the servo position."""
    try:
        if not SERVO_MIN_VALUE <= value <= SERVO_MAX_VALUE:
            raise ValueError("Servo value out of range")
        normalized_value = (value - SERVO_MIN_VALUE) / (SERVO_MAX_VALUE - SERVO_MIN_VALUE)
        servo.value = normalized_value * 2 - 1  # Scale to -1 to 1 range
        print(f"Servo set to value: {value}")
    except ValueError as e:
        print(f"Invalid servo value: {e}")
    except Exception as e:
        print(f"Error setting servo position: {e}")


def main():
    """Main function to control the servos."""
    try:
        servo1, servo2 = initialize_servos()
        while True:
            try:
                user_input = input("Enter servo values (e.g., 500, 300): ")
                servo1_value, servo2_value = map(int, user_input.split(','))
                set_servo_position(servo1, servo1_value)
                set_servo_position(servo2, servo2_value)
            except ValueError:
                print("Invalid input. Please enter two comma-separated integers.")
            except KeyboardInterrupt:
                print("\nExiting program.")
                break
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure servos are released on exit
        if 'servo1' in locals():
            servo1.close()
        if 'servo2' in locals():
            servo2.close()
        print("Program finished.")


if __name__ == "__main__":
    main()

