# uart_communication_rpi.py
# Reads data from a UART-connected device and prints it on Raspberry Pi
import serial
import time
import logging

# Configure logging for debugging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 0.1

def initialize_serial(port, baud, timeout_sec):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout_sec)
        logging.info(f"Serial connection established on {port} at {baud} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
        return None

def read_serial_data(serial_connection):
    """Reads a line of data from the serial port."""
    try:
        data = serial_connection.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        logging.error(f"Error reading from serial port: {e}")
        return None

def process_data(data):
    """Processes the received data and prints it."""
    if data:
        print(f'Received: {data}')

def main():
    """Main function to read and process data from the serial port."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return 1

    try:
        while True:
            data = read_serial_data(serial_connection)
            process_data(data)
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial connection closed.")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# Simple relay control program for Raspberry Pi using gpiozero
# Author: [Your Name]
# Date: [Current Date]

from gpiozero import DigitalOutputDevice
import sys

# Define the GPIO pins for the relays
RELAY_1_PIN = 20
RELAY_2_PIN = 21

def control_relay(relay_pin, state):
    """Controls a single relay."""
    try:
        relay = DigitalOutputDevice(relay_pin)
        if state == "ON":
            relay.on()
            print(f"Relay on pin {relay_pin} is now ON")
        elif state == "OFF":
            relay.off()
            print(f"Relay on pin {relay_pin} is now OFF")
        else:
            print(f"Invalid state '{state}' for relay on pin {relay_pin}")
    except Exception as e:
        print(f"Error controlling relay on pin {relay_pin}: {e}")
    finally:
        relay.close()  # Release the GPIO pin

def main():
    """Main function to control the relays."""
    try:
        # Check if the program was called with the correct number of arguments
        if len(sys.argv) != 3:
            print("Usage: python relay_control.py <relay_number> <state>")
            print("Example: python relay_control.py 1 ON")
            sys.exit(1)

        relay_number = int(sys.argv[1])
        state = sys.argv[2].upper()

        # Control the appropriate relay based on the relay_number
        if relay_number == 1:
            control_relay(RELAY_1_PIN, state)
        elif relay_number == 2:
            control_relay(RELAY_2_PIN, state)
        else:
            print(f"Invalid relay number: {relay_number}")

    except ValueError:
        print("Invalid relay number. Please enter a number.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        sys.exit(0)

if __name__ == "__main__":
    main()

